const o={ui:{fig:"Fig. 3",title:"Angoli a triangolo",svgLabel:"Un disegno isometrico di come si fanno gli angoli a triangolo: la borsa cucita sui lati e sul fondo, ogni angolo in basso aperto a triangolo con la cucitura laterale sulla cucitura del fondo, una linea segnata di traverso a metà della larghezza del fondo dalla fine della cucitura e cucita, la punta tagliata lasciando un piccolo margine, la borsa rivoltata, con il fondo piatto.",prev:"Passo precedente",dot:(a,l)=>a?`Passo ${a}: ${l}`:l,start:"Passo passo →",next:"Avanti →",overview:"Panoramica",stepOf:(a,l)=>`Passo ${a} di ${l}`,machine:a=>`Macchina: ${a.toLowerCase()}`,inThisStep:"In questo passo",takeApart:"Rimetti in piedi",putTogether:"Mostra il fondo",replay:"↻ Ripeti",parts:"Parti",allSteps:"Istruzioni passo passo",endView:"SEZIONE"},stitches:{straight:"Punto dritto"},labels:{rightSides:"dritto contro dritto",sidesBottom:"lati e fondo",aPouch:"una busta piatta",standUp:"mettila capovolta",openCorner:"apri l'angolo",seamOnSeam:"cucitura su cucitura",triangle:"un triangolo",seamEnd:"fine della cucitura",halfBase:"metà larghezza del fondo",baseWidth:"larghezza del fondo",sewLine:"cuci sulla linea",backstitch:"fermatura",bothCorners:"i due angoli",trimTip:"taglia la punta",smallAllowance:"un piccolo margine",turnOut:"rivolta sul dritto",flatBottom:"un fondo piatto",cornerSeam:"cucitura dell'angolo"},steps:[{title:"Angoli a triangolo",text:"Il fondo della borsa, la borsa capovolta: un fondo piatto, con la cucitura del fondo al centro e una breve cucitura di traverso a ogni estremità, dove la incontra la cucitura laterale. Tocca la borsa per rimetterla in piedi."},{title:"Cuci la borsa",text:"Appoggia il davanti sul dietro, dritto contro dritto, e cuci i lati e il fondo: una busta piatta, senza tagliare niente dagli angoli.",details:["Appoggia il davanti sul dietro, dritto contro dritto, e fissali con le clip.","Cuci i due lati e il fondo.","Dagli angoli non si taglia niente: il fondo si forma nei passi successivi.","Se la borsa è un solo pezzo piegato sul fondo, non c'è la cucitura del fondo: allora la cucitura laterale va sulla piega del fondo."]},{title:"Apri l'angolo",text:"Allarga il davanti e il dietro in un angolo in basso e appiattiscilo in modo che la cucitura laterale stia proprio sulla cucitura del fondo: l'angolo diventa un triangolo.",details:["Allarga il davanti e il dietro in un angolo in basso.","Appiattisci l'angolo in modo che la cucitura laterale stia esattamente sulla cucitura del fondo (o sulla piega del fondo).","Ora l'angolo è un triangolo, con la cucitura al centro fino alla fine della cucitura, sulla punta.","Apri allo stesso modo l'altro angolo in basso.","Nel disegno la borsa sta capovolta, appoggiata sull'apertura, così si vedono tutti e due gli angoli."]},{title:"Segna la linea",text:"Segna una linea di traverso sul triangolo, ad angolo retto con la cucitura, a metà della larghezza del fondo dalla fine della cucitura. Così la linea è lunga quanto il fondo è largo.",details:["Decidi quanto vuoi largo il fondo: è la larghezza del fondo.","Misura metà della larghezza del fondo lungo la cucitura, dalla fine della cucitura, dove le cuciture si incontrano sulla punta — non dalla punta del tessuto.","Lì traccia una linea di traverso sul triangolo, ad angolo retto con la cucitura. È lunga quanto il fondo è largo.","Più la linea è lontana dalla punta, più il fondo è largo. Segna allo stesso modo l'altro angolo."]},{title:"Cuci sulla linea",text:"Cuci sulla linea segnata, con una fermatura all'inizio e alla fine.",details:["Cuci sulla linea da un bordo all'altro del triangolo.","Fai la fermatura all'inizio e alla fine, così la cucitura tiene.","Cuci allo stesso modo l'altro angolo."]},{title:"Taglia la punta",text:"Taglia la punta di ogni triangolo, lasciando un piccolo margine oltre la cucitura.",details:["Taglia la punta lungo la cucitura, lasciando un piccolo margine di cucitura.","Non tagliare la cucitura.","Fai allo stesso modo tutti gli angoli in basso, e anche quelli della fodera, se la borsa è foderata."]},{title:"Rivolta",text:"Rivolta la borsa sul dritto: ha il fondo piatto, con una breve cucitura dell'angolo di traverso a ogni estremità.",details:["Rivolta la borsa sul dritto e spingi fuori gli angoli.","Il fondo è piatto e largo quanto era lunga la linea. A ogni estremità la cucitura laterale arriva a metà della cucitura dell'angolo."]}],legend:[{title:"Fondo",text:"piatto · largo quanto sono lunghe le cuciture degli angoli"},{title:"Cucitura del fondo",text:"unisce il davanti e il dietro · al centro del fondo"},{title:"Cuciture degli angoli",text:"cucite di traverso sull'angolo, a metà della larghezza del fondo dalla fine della cucitura"},{title:"Cuciture laterali",text:"ognuna arriva a metà di una cucitura dell'angolo"}]};export{o as default};
